module vga_tgen ( clk, clk_ena, rst, Thsync, Thgate, Thlen, Tvsync, Tvgate, 
        Tvlen, eol, eof, gate, hsync, vsync, csync, blank );
  input [7:0] Thsync;
  input [15:0] Thgate;
  input [15:0] Thlen;
  input [7:0] Tvsync;
  input [15:0] Tvgate;
  input [15:0] Tvlen;
  input clk, clk_ena, rst;
  output eol, eof, gate, hsync, vsync, csync, blank;
  wire   Hgate, vclk_ena, Vgate;

  vga_vtim_1 hor_gen ( .clk(clk), .ena(clk_ena), .rst(rst), .Tsync(Thsync), 
        .Tgate(Thgate), .Tlen(Thlen), .Sync(hsync), .Gate(Hgate), .doone(eol)
         );
  vga_vtim_0 ver_gen ( .clk(clk), .ena(vclk_ena), .rst(rst), .Tsync(Tvsync), 
        .Tgate(Tvgate), .Tlen(Tvlen), .Sync(vsync), .Gate(Vgate), .doone(eof)
         );
  OR2D0BWP12T30P140 U1 ( .A1(hsync), .A2(vsync), .Z(csync) );
  ND2D0BWP12T30P140 U2 ( .A1(Hgate), .A2(Vgate), .ZN(blank) );
